import {activeRole,scopeFor,localDate,recordByRef,sourcesValid} from './model.mjs';
export const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const icon=name=>`<svg class="icon" aria-hidden="true"><use href="#i-${name}"/></svg>`;
export const btn=(action,label,extra='',cls='small-button')=>`<button type="button" class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
export const field=(name,label,value='',type='text',extra='')=>`<label class="field-label" for="f-${name}">${label}</label><input class="text-field" id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}>`;
export const area=(name,label,value='',extra='')=>`<label class="field-label" for="f-${name}">${label}</label><textarea class="text-field" id="f-${name}" name="${name}" ${extra}>${esc(value)}</textarea>`;
export const select=(name,label,options,value)=>`<label class="field-label" for="f-${name}">${label}</label><select class="text-field" id="f-${name}" name="${name}">${options.map(([v,t])=>`<option value="${esc(v)}" ${String(value)===String(v)?'selected':''}>${esc(t)}</option>`).join('')}</select>`;
export const submit=label=>`<div class="sheet-actions"><button class="primary" type="submit">${label}</button></div>`;
export const empty=text=>`<p class="empty">${text}</p>`;
export const meta=text=>`<span class="meta">${esc(text)}</span>`;
export const liveRoles=state=>state.roles.filter(r=>!r.deleted);
export const roleName=(state,roleId)=>roleId==='user'?state.user.name:(state.roles.find(r=>r.id===roleId)?.name||'已移除角色');
export const avatar=(state,roleId,cls='avatar')=>`<img class="${cls}" data-media="${esc((roleId==='user'?state.user.avatar:state.roles.find(r=>r.id===roleId)?.avatar)||'builtin-flowers')}" alt="${esc(roleName(state,roleId))}的头像">`;
const avatarPicker=(id,label)=>`<div class="avatar-picker"><img class="avatar-picker-image" data-avatar-preview data-media="${esc(id||'builtin-flowers')}" alt="${label}"><div><strong>${label}</strong>${btn('pick-avatar','从图库选择','','secondary')}<span class="meta">选择设备里的照片</span></div><input type="hidden" name="avatar" value="${esc(id||'builtin-flowers')}"></div>`;
export const checks=(state,name,selected=[],allowed=liveRoles(state))=>`<div class="check-list">${allowed.map(r=>`<label class="check-row"><input type="checkbox" name="${name}" value="${r.id}" ${selected.includes(r.id)?'checked':''}>${esc(r.name)}</label>`).join('')}</div>`;
const dateTime=value=>new Date(value).toLocaleString('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'});
export function tasksHTML(scope,targetId=null){
  return scope.tasks.filter(t=>(!targetId||t.targetId===targetId)&&t.status!=='done').slice(-12).map(t=>`<div class="task-line"><span>${esc(t.authorName||'角色')} · ${{waiting:'等待回复',running:'正在生成',failed:'生成失败',cancelled:'已停止'}[t.status]}</span>${t.error?meta(t.error):''}<div class="toolbar">${['failed','cancelled'].includes(t.status)?btn('retry-task','重试',`data-id="${t.id}"`):btn('cancel-task','停止',`data-id="${t.id}"`)}</div></div>`).join('');
}
const searchForm=(route,label='搜索关键词')=>`<form id="search-form"><div class="toolbar"><input class="text-field" name="query" aria-label="${label}" placeholder="${label}" value="${esc(route.query||'')}"><button class="secondary">搜索</button>${btn('favorites-filter',route.favorites?'查看全部':'只看收藏')}</div></form>`;
function matches(text,query){return !query||text.toLocaleLowerCase().includes(query.toLocaleLowerCase());}
function mediaHTML(ids){return (ids||[]).map(mid=>`<img class="post-image" data-media="${esc(mid)}" alt="附图">`).join('');}
function favorite(scope,type,id){return scope.favorites.some(f=>f.type===type&&f.id===id);}
function entryActions(scope,type,record){return `<div class="toolbar">${btn('favorite',favorite(scope,type,record.id)?'已收藏':'收藏',`data-kind="${type}" data-id="${record.id}" aria-pressed="${favorite(scope,type,record.id)}"`)}${btn('edit-record','编辑',`data-kind="${type}" data-id="${record.id}"`)}${(record.sourceRefs||[]).length?btn('view-sources','查看来源',`data-kind="${type}" data-id="${record.id}"`):''}${btn('delete-record','移入回收站',`data-kind="${type}" data-id="${record.id}"`)}</div>`;}

export function renderPanel(state,route){
  const role=activeRole(state),scope=scopeFor(state,route.key)||scopeFor(state),world=state.worlds.find(w=>w.id===scope?.worldId),roles=liveRoles(state);
  const common={kicker:'我的手机'};
  let title='',html='',actions='';
  switch(route.name){
  case 'sources':{
    const record=recordByRef(scope,{type:route.kind,id:route.id});title='内容来源';html=(record.sourceRefs?.length?record.sourceRefs:record.originalSources||[]).map(ref=>{const original=recordByRef(scope,ref);return `<div class="card"><p class="prose">${esc(original&&!original.deleted?(original.text||original.title):'原内容已移除')}</p>${original&&!original.deleted?btn('open-source','打开原文',`data-kind="${ref.type}" data-id="${ref.id}"`):''}</div>`;}).join('')||empty('这是一条手工记录。');break;}
  case 'chats':
    title='消息';actions=btn('chat-create',icon('plus'),'aria-label="新建聊天"','icon-button');
    html=`<form id="search-form" class="chat-list-search" role="search">${icon('search')}<input name="query" type="search" aria-label="搜索会话" placeholder="搜索会话" value="${esc(route.query||'')}"><button class="sr-only" type="submit">搜索</button></form><div class="conversation-list">${(scope?.chats||[]).filter(c=>matches(`${c.name} ${c.members.map(id=>roleName(state,id)).join(' ')}`,route.query)).slice().sort((a,b)=>(b.messages.at(-1)?.at||b.at||0)-(a.messages.at(-1)?.at||a.at||0)).map(c=>{const last=c.messages.filter(m=>!m.deleted).at(-1),unread=c.messages.filter(m=>!m.deleted&&m.authorId!=='user'&&m.at>c.readAt).length;return `<button class="conversation-row" data-action="open-chat" data-id="${c.id}">${avatar(state,c.members[0])}<span class="conversation-copy"><span class="conversation-top"><strong>${esc(c.kind==='private'?(c.name||roleName(state,c.members[0])):c.name)}</strong>${last?`<time>${localDate(new Date(last.at))===localDate()?new Date(last.at).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'}):new Date(last.at).toLocaleDateString('zh-CN',{month:'numeric',day:'numeric'})}</time>`:''}</span><span class="conversation-preview">${c.draft?`<em>草稿</em> ${esc(c.draft)}`:esc(last?.text||'开始聊聊吧')}${unread?`<b class="badge">${unread}</b>`:''}</span>${c.legacyLabel?meta(c.legacyLabel):c.kind==='group'?meta(`${c.members.length} 位联系人`):''}</span></button>`;}).join('')||(route.query?empty('没有找到这个会话'):roles.length?empty('点右上角 +，开始新的聊天。'):empty('添加一位联系人，开始第一段聊天。')+btn('new-role','添加联系人','','primary full-width'))}</div>`;break;
  case 'new-chat':
    title='发起私聊';html=`<p class="hint">选择一位联系人，开始聊天。</p>${roles.map(r=>`<button class="list-row" data-action="start-private" data-id="${r.id}">${avatar(state,r.id)}<span><strong>${esc(r.name)}</strong><small>${esc(r.relation||'私聊')}</small></span>${icon('arrow')}</button>`).join('')}${btn('new-role','添加联系人','','secondary full-width')}`;break;
  case 'new-group':
    title='创建群聊';html=roles.length<2?`${empty('添加至少两位联系人后就能建群。')}${btn('new-role','添加联系人','','primary')}`:`<form id="new-chat-form">${field('name','群聊名字','新的群聊','text','required')}<span class="field-label">选择群成员</span>${checks(state,'members',[])}${submit('创建群聊')}</form>`;break;
  case 'chat-options':{
    const chat=scope.chats.find(c=>c.id===route.id);title='会话设置';html=`<div class="chat-members">${chat.members.map(id=>`<div>${avatar(state,id)}<span>${esc(roleName(state,id))}</span></div>`).join('')}</div><form id="chat-settings-form">${field('name',chat.kind==='group'?'群聊名字':'会话备注',chat.name,'text','required')}${chat.kind==='group'?`<span class="field-label">群成员</span>${checks(state,'members',chat.members)}`:''}${submit('保存')}</form><div class="settings-group"><button class="setting-link" data-action="chat-search"><span>查找聊天 / 收藏</span>${icon('arrow')}</button><button class="setting-link" data-action="respond"><span>选择这次回复的角色</span>${icon('arrow')}</button><button class="setting-link" data-action="tasks"><span>回复进度与记录</span>${icon('arrow')}</button></div>`;break;}
  case 'chat-create':
    title='新建聊天';html=`<div class="stack">${btn('new-chat',icon('chat')+'发起私聊','','secondary')}${btn('new-group',icon('plus')+'创建群聊','','secondary')}</div>`;break;
  case 'respond':{
    const chat=scope.chats.find(c=>c.id===route.id);title='这次由谁回复';html=`<form id="respond-form">${checks(state,'members',chat.members,roles.filter(r=>chat.members.includes(r.id)))}<p class="hint">按选择顺序分别回复，失败者可以单独重试。</p>${submit('让角色回复')}</form>${tasksHTML(scope,chat.id)}`;break;}
  case 'chat-search':{
    const chat=scope.chats.find(c=>c.id===route.id);title='查找聊天';html=searchForm(route,'搜索关键词、名字或日期')+chat.messages.filter(m=>!m.deleted&&matches(`${m.text} ${m.authorName} ${localDate(new Date(m.at))}`,route.query)&&(!route.favorites||favorite(scope,'message',m.id))).map(m=>`<button class="list-row" data-action="jump-message" data-id="${m.id}"><span><strong>${esc(m.authorName)} · ${localDate(new Date(m.at))}</strong><small>${esc(m.text||'附件')}</small></span></button>`).join('');break;}
  case 'message-actions':{
    const m=recordByRef(scope,{type:'message',id:route.id});title=m.authorName;html=`<p class="prose">${esc(m.text)}</p><div class="toolbar">${btn('favorite',favorite(scope,'message',m.id)?'取消收藏':'收藏消息',`data-kind="message" data-id="${m.id}"`)}${btn('quote-message','引用回复',`data-id="${m.id}"`)}${btn('memory-from-message','存为回忆',`data-id="${m.id}"`)}${btn('event-from-message','存为约定',`data-id="${m.id}"`)}${btn('speak-message','朗读并保存音频',`data-id="${m.id}"`)}${btn('edit-record','编辑消息',`data-kind="message" data-id="${m.id}"`)}${btn('delete-record','移入回收站',`data-kind="message" data-id="${m.id}"`)}</div>`;break;}
  case 'roles':
    title='联系人';actions=btn('new-role',icon('plus'),'aria-label="添加联系人"','icon-button');
    html=`<p class="hint">添加角色成为联系人，随时私聊或邀请进群。</p>${roles.map(r=>`<div class="card"><div class="card-head">${avatar(state,r.id)}<div><strong>${esc(r.name)}</strong>${meta(r.relation||'还没有填写关系')}</div></div><div class="toolbar">${btn('start-private','发消息',`data-id="${r.id}"`)}${btn('edit-role','编辑联系人',`data-id="${r.id}"`)}${btn('memories','共同回忆',`data-owner="${r.id}"`)}</div></div>`).join('')||`${empty('先添加一位想聊天的人吧。')}${btn('new-role','添加联系人','','primary')}`}<div class="toolbar">${btn('import-role','导入角色 JSON')}${btn('role-trash','已移除联系人')}</div>`;break;
  case 'role-form':{
    const r=route.values||state.roles.find(r=>r.id===route.id)||{name:'',persona:'',relation:'',metOn:localDate(),worldId:state.phone.worldId,worldMode:'inherit',avatar:'builtin-flowers'};
    const shared=state.worlds.find(w=>w.id===state.phone.worldId);
    title=route.id?'编辑联系人':route.imported?'导入角色预览':'添加联系人';
    html=`${route.imported?'<p class="hint">已读取姓名、人设与关系，保存后加入联系人。</p>':''}<form id="role-form">${avatarPicker(r.avatar,'联系人头像')}${field('name','名字',r.name,'text','required maxlength="40"')}${area('persona','人设与说话习惯',r.persona,'maxlength="20000" placeholder="例如：安静细心，说话简短，喜欢摄影"')}${area('relation','与你的关系',r.relation,'maxlength="4000" placeholder="例如：同学、朋友，或你设定的关系"')}<div class="world-summary"><div><strong>手机共同背景</strong>${meta(state.phone.worldEnabled?(shared?.body?shared.name:'尚未填写'):'已关闭')}</div>${btn('worlds','设置背景','','small-button')}<p class="hint">填写时代、地点和共同设定，所有联系人默认共用。</p></div><details ${r.worldMode!=='inherit'?'open':''}><summary>更多设置</summary>${field('metOn','相遇日期',r.metOn,'date','required')}${select('worldMode','这个联系人的背景',[['inherit','跟随手机的共同背景'],['off','不使用世界背景'],['own','使用单独的背景']],r.worldMode||'inherit')}<div data-own-world ${r.worldMode==='own'?'':'hidden'}>${select('worldId','单独的背景',state.worlds.map(w=>[w.id,w.name]),r.worldId)}<div class="toolbar">${btn('choose-own-world','编辑所选背景')}${btn('new-world','新建单独背景','data-select-for="role"')}</div></div>${!state.phone.worldEnabled?'<p class="hint">手机的背景总开关已关闭，打开后才会在回复中使用背景。</p>':''}</details>${submit(route.id?'保存联系人':'添加联系人')}</form>${route.id?`<div class="toolbar">${btn('proactive','主动来信设置',`data-id="${r.id}"`)}${btn('delete-role','移除联系人',`data-id="${r.id}"`,'small-button danger')}</div>`:''}`;break;}
  case 'role-trash':
    title='已移除联系人';html=state.roles.filter(r=>r.deleted).map(r=>`<div class="card"><strong>${esc(r.name)}</strong>${meta('聊天和署名保留，恢复后可继续使用。')}${btn('restore-role','恢复角色',`data-id="${r.id}"`)}</div>`).join('')||empty('这里还没有移除的角色。');break;
  case 'worlds':{
    const current=state.worlds.find(w=>w.id===state.phone.worldId);
    title='世界背景';
    html=`<p class="hint">填写你和联系人生活的时代、地点与共同设定，聊天、动态和日记都会采用。</p><label class="switch-row"><span>在互动中使用世界背景</span><input id="phone-world-enabled" class="switch" type="checkbox" ${state.phone.worldEnabled?'checked':''}></label><div class="card world-current"><div class="card-head"><strong>${esc(current.name)}</strong><span class="badge">共同背景</span></div><p class="prose">${esc(current.body||'还没填写背景。点下方按钮写下你的设定。')}</p>${btn('edit-current-world',current.body?'编辑背景':'填写背景','','primary')}</div><div class="toolbar">${btn('new-world','新建背景')}</div>${state.worlds.filter(w=>w.id!==state.phone.worldId).map(w=>`<div class="card"><strong>${esc(w.name)}</strong><p class="hint">${esc(w.body?.slice(0,100)||'尚未填写')}</p><div class="toolbar">${btn('use-world','设为共同背景',`data-id="${w.id}"`)}${btn('edit-world','编辑',`data-id="${w.id}"`)}</div></div>`).join('')}`;break;}
  case 'world-form':{
    const w=state.worlds.find(w=>w.id===route.id)||{name:'',body:'',timeMode:'real',date:localDate()};title=route.id?'编辑世界背景':'新建世界背景';html=`<form id="world-form">${field('name','背景名称',w.name,'text','required maxlength="60" placeholder="例如：海边小城"')}${area('body','时代、地点与共同设定',w.body,'maxlength="24000" rows="9" placeholder="例如：我们住在一座临海小城，在同一所大学读书……"')}<details><summary>故事时间</summary>${select('timeMode','日历时间',[['real','现实日期'],['story','故事日期']],w.timeMode)}${field('date','故事日期',w.date,'date','required')}</details>${submit(route.id?'保存背景':route.selectFor==='role'?'保存并用于这位联系人':'保存并设为共同背景')}</form>`;break;}
  case 'memories':
    title='共同回忆';html=`<div class="toolbar">${btn('new-memory','手写回忆')}${btn('generate-memory','整理角色经历')}</div>${scope.memories.filter(m=>!m.deleted&&(!route.owner||m.participants.includes(route.owner))).map(m=>`<div class="card"><p class="prose">${esc(m.text)}</p>${meta(m.participants.map(cid=>roleName(state,cid)).join('、'))}${meta(m.stale||!sourcesValid(scope,m)?'来源已变化，请检查后更新':m.manual?'手工记录':`来自 ${m.sourceRefs.length} 条经历`)}<div class="toolbar">${btn('toggle-memory',m.enabled?'已启用':'已停用',`data-id="${m.id}" aria-pressed="${m.enabled}"`)}${btn('pin-memory',m.pinned?'已固定':'固定',`data-id="${m.id}"`)}${btn('view-sources','查看来源',`data-kind="memory" data-id="${m.id}"`)}${btn('edit-record','编辑',`data-kind="memory" data-id="${m.id}"`)}${btn('delete-record','移入回收站',`data-kind="memory" data-id="${m.id}"`)}</div></div>`).join('')||empty('重要的话和一起经历的事，可以留在这里。')}${tasksHTML(scope)}`;break;
  case 'memory-form':{
    const m=scope.memories.find(m=>m.id===route.id)||{text:route.text||'',participants:[route.owner||role?.id].filter(Boolean),enabled:true,pinned:false};title=route.id?'编辑回忆':'留下一段回忆';html=`<form id="memory-form">${area('text','想记住的事',m.text,'required maxlength="12000"')}<span class="field-label">哪些角色知道这件事</span>${checks(state,'participants',m.participants,route.allowed?roles.filter(r=>route.allowed.includes(r.id)):roles)}<label class="check-row"><input name="enabled" type="checkbox" ${m.enabled?'checked':''}>在后续回复中使用</label><label class="check-row"><input name="pinned" type="checkbox" ${m.pinned?'checked':''}>固定这段回忆</label>${submit('保存回忆')}</form>`;break;}
  case 'calendar':
    title='约定与纪念日';html=`${meta(world?.timeMode==='story'?`故事日期 · ${world.date}`:'现实日历')}<div class="toolbar">${btn('new-event','添加约定')}${btn('diary','回到日记')}</div>${scope.events.filter(e=>!e.deleted).sort((a,b)=>a.date.localeCompare(b.date)).map(e=>`<div class="calendar-item"><strong>${esc(e.title)}</strong>${meta(`${e.date} ${e.time||''}${e.repeat==='yearly'?' · 每年':''} · ${{planned:'待赴约',done:'已完成',cancelled:'已取消'}[e.status]}`)}${meta(e.participants.map(cid=>roleName(state,cid)).join('、'))}<div class="toolbar">${btn('edit-record','编辑',`data-kind="event" data-id="${e.id}"`)}${e.status==='planned'?btn('complete-event','记录已完成',`data-id="${e.id}"`):''}${e.status!=='cancelled'?btn('cancel-event','取消约定',`data-id="${e.id}"`):''}</div></div>`).join('')||empty('从聊天留下一个约定，或记住一个特别的日子。')}`;break;
  case 'event-form':{
    const e=scope.events.find(e=>e.id===route.id)||{title:route.text||'',date:world?.timeMode==='story'?world.date:localDate(),time:'',repeat:'none',participants:[route.owner||role?.id].filter(Boolean),note:''};title=route.id?'编辑约定':'添加约定';html=`<form id="event-form">${field('title','约定或纪念日',e.title,'text','required maxlength="120"')}<div class="two-fields">${field('date','日期',e.date,'date','required')}${field('time','时间（可选）',e.time,'time')}</div>${select('repeat','重复',[['none','仅这一次'],['yearly','每年纪念']],e.repeat)}<span class="field-label">参与角色</span>${checks(state,'participants',e.participants)}${area('note','备注',e.note)}${submit('确认并保存约定')}</form>`;break;}
  case 'diary':
    title='日记';html=`<div class="toolbar">${btn('new-diary','自己写')}${btn('generate-diary','角色写日记')}${btn('calendar','约定与纪念日')}</div>${searchForm(route,'搜索正文、作者或日期')}${scope.diaries.filter(d=>!d.deleted&&matches(`${d.title} ${d.text} ${d.authorName} ${d.date}`,route.query)&&(!route.favorites||favorite(scope,'diary',d.id))).sort((a,b)=>b.date.localeCompare(a.date)||b.at-a.at).map(d=>`<article class="card" id="record-${d.id}"><div class="card-head">${avatar(state,d.authorId)}<div><strong>${esc(d.title)}</strong>${meta(`${d.authorName} · ${d.date}${d.status==='draft'?' · 草稿':''}`)}</div></div><p class="prose">${esc(d.text)}</p>${d.stale?meta('原经历已变化，可重新整理或自行修订。'):''}${entryActions(scope,'diary',d)}</article>`).join('')}${tasksHTML(scope)}`;break;
  case 'diary-form':{
    const d=scope.diaries.find(d=>d.id===route.id)||{title:'',text:'',date:world?.timeMode==='story'?world.date:localDate(),authorId:'user'};title=route.id?'编辑日记':'写下今天';html=`<form id="diary-form">${field('title','标题',d.title,'text','maxlength="120"')}${field('date','日期',d.date,'date','required')}${area('text','日记正文',d.text,'required maxlength="30000"')}${submit('保存日记')}</form>`;break;}
  case 'generate-diary':
    title='让角色写日记';html=`<form id="generate-diary-form">${select('authorId','日记作者',roles.map(r=>[r.id,r.name]),route.owner||role?.id)}${field('date','记录哪一天',world?.timeMode==='story'?world.date:localDate(),'date','required')}<p class="hint">从作者当天知道的聊天、动态和已完成约定整理，生成后保存为可编辑草稿。</p>${submit('生成日记')}</form>`;break;
  case 'moments':
    title='朋友圈';html=`<div class="toolbar">${btn('new-post','发动态')}${btn('generate-post','角色发动态')}</div>${searchForm(route,'搜索动态、作者或日期')}${scope.posts.filter(p=>!p.deleted&&matches(`${p.text} ${p.authorName} ${localDate(new Date(p.at))}`,route.query)&&(!route.favorites||favorite(scope,'post',p.id))).slice().reverse().map(p=>`<article class="card" id="record-${p.id}"><div class="card-head">${avatar(state,p.authorId)}<div><strong>${esc(p.authorName)}</strong>${meta(dateTime(p.at))}</div></div><p class="prose">${esc(p.text)}</p>${mediaHTML(p.media)}${meta('可见：'+p.audience.map(cid=>roleName(state,cid)).join('、'))}<div class="toolbar">${btn('like-post',`${p.likes.includes('user')?'已赞':'赞'} ${p.likes.length||''}`,`data-id="${p.id}"`)}${btn('comment-post','评论',`data-id="${p.id}"`)}${btn('role-comments','让角色回复',`data-id="${p.id}"`)}</div>${entryActions(scope,'post',p)}<div class="comments">${p.comments.filter(c=>!c.deleted).map(c=>`<div class="comment"><strong>${esc(c.authorName)}</strong>${c.replyTo?`<span class="reply-target"> 回复 ${esc(p.comments.find(x=>x.id===c.replyTo)?.authorName||'原评论')}</span>`:''}<p class="prose">${esc(c.text)}</p>${btn('reply-comment','回复',`data-post="${p.id}" data-id="${c.id}"`)}${btn('role-comments','角色接话',`data-id="${p.id}" data-reply="${c.id}"`)}</div>`).join('')}</div>${tasksHTML(scope,p.id)}</article>`).join('')||empty('分享一张照片，或今天想说的一句话。')}`;break;
  case 'post-form':{
    const p=scope.posts.find(p=>p.id===route.id)||{text:'',audience:roles.map(r=>r.id),media:[]};title=route.id?'编辑动态':'发一条动态';html=`<form id="post-form">${area('text','想分享什么',p.text,'maxlength="6000"')}<span class="field-label">配图（可多选）</span><div class="media-grid">${state.media.filter(m=>m.type.startsWith('image/')).map(m=>`<label class="check-row"><input type="checkbox" name="media" value="${m.id}" ${p.media.includes(m.id)?'checked':''}><span>${esc(m.name)}</span></label>`).join('')}</div><span class="field-label">谁能看到和回复</span>${checks(state,'audience',p.audience)}${submit('发布动态')}</form>`;break;}
  case 'comment-form':
    title=route.replyTo?'回复评论':'评论动态';html=`<form id="comment-form">${area('text','评论内容','','required maxlength="4000"')}${submit('发送评论')}</form>`;break;
  case 'role-comments':
    title='邀请角色回复';html=`<form id="role-comments-form">${checks(state,'members',scope.posts.find(p=>p.id===route.id).audience,roles.filter(r=>scope.posts.find(p=>p.id===route.id).audience.includes(r.id)))}${submit('分别回复')}</form>`;break;
  case 'generate-post':case 'generate-memory':
    title=route.name==='generate-post'?'角色发动态':'整理共同回忆';html=`<form id="generate-role-form">${select('authorId','选择角色',roles.map(r=>[r.id,r.name]),route.owner||role?.id)}${route.name==='generate-post'?`<span class="field-label">动态可见角色</span>${checks(state,'audience',roles.map(r=>r.id))}`:'<p class="hint">整理该角色已知的经历，保存后可以编辑、固定或停用。</p>'}${submit('开始生成')}</form>`;break;
  case 'edit-message':
    title='编辑消息';html=`<form id="edit-message-form">${area('text','消息正文',recordByRef(scope,{type:'message',id:route.id}).text,'required')}${submit('保存修改')}</form>`;break;
  default:return renderOther(state,route,common);
  }
  return {...common,title,html,actions};
}

function renderOther(state,route,common){
  const role=activeRole(state),scope=scopeFor(state,route.key)||scopeFor(state);let title='',html='';
  switch(route.name){
  case 'settings':
    title='设置';html=`${[['api','API 与模型'],['voice-settings','语音服务'],['data','备份、恢复与回收站'],['tasks','生成记录']].map(([action,label])=>`<button class="setting-link" data-action="${action}"><span>${label}</span>${icon('arrow')}</button>`).join('')}${meta('内容保存在这个浏览器中；生成时使用你配置的服务。')}`;break;
  case 'api':{
    const c=route.values||state.connections.text;title='API 与模型';html=`<div class="toolbar">${btn('import-api','导入连接 JSON')}</div><p class="hint">支持兼容 Chat Completions 的服务。填写到接口根路径，例如 https://你的服务/v1。</p><form id="api-form">${field('baseUrl','服务地址',c.baseUrl,'url','required autocomplete="off"')}${field('secret','API 密钥（留空保留已存密钥）',route.values?.secret||'','password','autocomplete="new-password"')}${field('model','模型名称',c.model,'text','required list="api-models"')}<datalist id="api-models"></datalist><div class="toolbar">${btn('models','获取模型列表')}${btn('test-api','测试当前填写的连接')}</div><p class="task-status" id="api-status" role="status"></p><details><summary>回复参数</summary>${field('temperature','温度',c.temperature??.8,'number','min="0" max="2" step="0.1"')}${field('maxTokens','最多回复 Token',c.maxTokens||900,'number','min="64" max="8000"')}</details>${submit('保存连接')}</form>${btn('clear-key','清除已保存的密钥','data-kind="text"')}<p class="hint">密钥保存在本机服务设置中，备份会自动排除。</p>`;break;}
  case 'voice-settings':
    title='语音服务';html=`<p class="hint">语音识别和角色朗读分别接入兼容接口，可以使用不同服务。</p><form id="voice-form">${['transcription','speech'].map(kind=>{const c=state.connections[kind];return `<details ${kind==='speech'?'open':''}><summary>${kind==='speech'?'角色朗读':'录音识别'}</summary>${field(kind+'Url','服务地址',c.baseUrl,'url')}${field(kind+'Key','密钥（留空保留）','','password','autocomplete="new-password"')}${field(kind+'Model','模型',c.model)}${kind==='speech'?field('speechVoice','声音名称',c.voice):''}${btn('clear-key','清除这个密钥',`data-kind="${kind}"`)}</details>`;}).join('')}${submit('保存语音设置')}</form>`;break;
  case 'identity':
    title='我的资料';html=`<form id="identity-form">${avatarPicker(state.user.avatar,'我的头像')}${field('name','你的称呼',state.user.name,'text','required maxlength="40"')}${area('description','想让角色知道的自己',state.user.description,'maxlength="4000"')}${submit('保存资料')}</form>`;break;
  case 'appearance':{
    const a=state.phone.appearance;title='主题与壁纸';html=`<form id="appearance-form">${select('theme','主题',[['light','日光'],['dark','夜色']],a.theme)}<label class="switch-row"><span>轻玻璃效果</span><input class="switch" name="blur" type="checkbox" ${a.blur?'checked':''}></label>${select('wallpaper','手机壁纸',state.media.filter(m=>m.type.startsWith('image/')).map(m=>[m.id,m.name]),a.wallpaper)}${select('chatBackground','聊天背景',[['','跟随手机壁纸'],...state.media.filter(m=>m.type.startsWith('image/')).map(m=>[m.id,m.name])],a.chatBackground)}${select('fontScale','阅读字号',[[1,'标准 · 100%'],[1.5,'大字 · 150%'],[2,'特大 · 200%']],a.fontScale)}<label class="switch-row"><span>桌面音乐组件</span><input class="switch" name="music" type="checkbox" ${a.music?'checked':''}></label><div class="sheet-actions">${btn('preview-appearance','预览','','secondary')}<button class="primary">保存外观</button></div></form><p class="hint">壁纸与外观应用于整部手机。</p>`;break;}
  case 'proactive':{
    const r=state.roles.find(r=>r.id===route.id),p=r.proactive;title=r.name+'的主动来信';html=`<form id="proactive-form"><label class="switch-row"><span>允许角色主动来信</span><input class="switch" name="enabled" type="checkbox" ${p.enabled?'checked':''}></label>${field('interval','最短间隔（分钟）',p.interval,'number','min="5" max="10080" required')}${field('dailyLimit','每日最多几次',p.dailyLimit,'number','min="1" max="20" required')}<div class="two-fields">${field('quietStart','安静时段开始（小时）',p.quietStart,'number','min="0" max="23" required')}${field('quietEnd','安静时段结束（小时）',p.quietEnd,'number','min="0" max="23" required')}</div><p class="hint">应用打开时按频率检查，优先联系当天的约定或纪念日。生成会使用当前 API；关闭页面后暂停，也不会补发积压问候。</p>${submit('保存来信规则')}</form>`;break;}
  case 'album':case 'attachments':{
    const attachments=route.name==='attachments';title=attachments?'选一张图片或表情':'相册';html=`<div class="toolbar">${btn('upload-images','添加图片')}${btn('album-filter',route.category==='表情'?'全部图片':'只看表情')}</div><div class="media-grid">${state.media.filter(m=>m.type.startsWith('image/')&&(!route.category||m.category===route.category)).map(m=>`<button data-action="${attachments?'attach-image':'media-detail'}" data-id="${m.id}"><img data-media="${m.id}" alt="${esc(m.name)}"><span>${esc(m.name)}</span></button>`).join('')}</div>`;break;}
  case 'media-detail':{
    const m=state.media.find(m=>m.id===route.id);title=m.name;html=`<img class="media-view" data-media="${m.id}" alt="${esc(m.name)}"><div class="toolbar">${btn('media-wallpaper','设为壁纸',`data-id="${m.id}"`)}${btn('media-avatar','设为我的头像',`data-id="${m.id}"`)}${btn('media-sticker',m.category==='表情'?'移出表情':'收为表情',`data-id="${m.id}"`)}${btn('open-original','查看原图',`data-id="${m.id}"`)}</div>${field('mediaName','图片名称',m.name)}${btn('rename-media','保存名称',`data-id="${m.id}"`)}`;break;}
  case 'music':{
    const track=state.media.find(m=>m.id===scope.playback.trackId)||state.media.find(m=>m.id==='builtin-music');const listening=scope.listening.find(l=>!l.endedAt);
    title='音乐与一起听';html=`<img class="big-cover" src="assets/portrait-birds.png" alt="飞鸟插画封面"><h3 class="player-title">${esc(track.name)}</h3><p class="player-subtitle">${listening?'正在与 '+listening.participants.map(cid=>roleName(state,cid)).join('、')+' 一起听':'选一首歌，留一会儿时间'}</p><label class="sr-only" for="seek">播放进度</label><input class="player-range" id="seek" type="range" min="0" max="100" step=".1"><div class="player-times"><span data-elapsed>0:00</span><span data-duration>0:24</span></div><div class="player-buttons">${btn('previous-track',icon('back'),'aria-label="上一首"','icon-button')}${btn('play',icon('play'),'aria-label="播放音乐"','play-button')}${btn('next-track',icon('arrow'),'aria-label="下一首"','icon-button')}</div><label class="volume-row">音量<input id="volume" type="range" min="0" max="1" step=".05" value="${scope.playback.volume}"></label><div class="toolbar">${btn('upload-music','添加音乐')}${btn('listen-together',listening?'结束一起听':'邀请角色一起听')}${btn('share-song','分享到聊天')}${listening?btn('choose-song','让角色选歌'):''}</div>${scope.playlist.map(mid=>{const m=state.media.find(m=>m.id===mid);return `<button class="list-row" data-action="select-track" data-id="${mid}"><span>${esc(m?.name||'曲目缺失')}</span>${mid===track.id?'<span class="badge">当前</span>':''}</button>`;}).join('')}<details><summary>一起听记录</summary>${scope.listening.slice().reverse().map(l=>`<div class="listen-history">${esc(l.participants.map(cid=>roleName(state,cid)).join('、'))} · ${dateTime(l.at)} · ${Math.floor((l.seconds||0)/60)} 分 ${(Math.floor(l.seconds||0)%60)} 秒${l.endedAt?'':' · 进行中'}${meta(l.tracks.map(mid=>state.media.find(m=>m.id===mid)?.name||'歌曲').join(' / '))}</div>`).join('')||empty('开始一起听后，实际播放时间会记在这里。')}</details>`;break;}
  case 'listen-form':
    title='邀请一起听';html=`<form id="listen-form">${checks(state,'members',[])}${submit('开始一起听')}</form>`;break;
  case 'share-song':
    title='分享到聊天';html=scope.chats.filter(c=>c.members.some(id=>state.roles.some(r=>r.id===id&&!r.deleted))).map(c=>`<button class="list-row" data-action="share-song-to" data-id="${c.id}">${avatar(state,c.members[0])}<span>${esc(c.name)}</span>${icon('arrow')}</button>`).join('');break;
  case 'record':
    title='录一段声音';html=`<p class="hint">录音最多 60 秒。录好后可先试听、转成文字或补充文字，再发送。</p><div id="recorder-content"><div class="toolbar">${btn('start-recording','开始录音','','primary')}${btn('upload-voice','上传已有录音','','secondary')}</div></div><p id="record-status" class="task-status" role="status"></p>`;break;
  case 'data':
    title='备份与恢复';html=`<p class="hint">备份包含联系人、背景、记录和原始附件，自动排除服务密钥。</p><div class="stack">${btn('export','导出完整备份','','primary')}${btn('import-backup','导入备份并预览','','secondary')}${btn('restore-points','恢复点','','secondary')}${state.migration?.personalPhone?.draftCopies?.length?btn('legacy-drafts','查看保留的旧草稿','','secondary'):''}${btn('trash','内容回收站','','secondary')}</div>`;break;
  case 'backup-preview':
    title='恢复备份预览';html=`<p class="hint">备份中的内容将替换当前内容。恢复前会自动留下当前完整记录的恢复点。服务密钥需要重新填写。</p><div class="card">${meta(`角色 ${route.summary.roles} 位 · 附件 ${route.summary.media} 个`)}</div>${btn('apply-backup','恢复这份备份','','primary')}`;break;
  case 'legacy-drafts':
    title='保留的旧草稿';html=`<p class="hint">整理旧记录时保留了这些同名草稿。打开后可继续编辑，当前未完成的草稿也会保留在这里。</p>${(state.migration?.personalPhone?.draftCopies||[]).map((d,i)=>`<div class="card"><strong>${esc(d.value.name||d.value.title||'未完成的草稿')}</strong><p class="prose">${esc(d.value.text||d.value.body||d.value.persona||'还有未保存的设置')}</p>${btn('open-legacy-draft','打开草稿',`data-index="${i}"`)}</div>`).join('')}`;break;
  case 'restore-points':
    title='恢复点';html=(route.points||[]).map(key=>btn('rollback',new Date(Number(key.replace('restore-',''))).toLocaleString('zh-CN'),`data-id="${key}"`,'list-row')).join('')||empty('恢复备份前会自动创建恢复点。');break;
  case 'trash':
    title='内容回收站';html=['message','post','diary','memory','event'].flatMap(type=>{const rows=type==='message'?scope.chats.flatMap(c=>c.messages):scope[{post:'posts',diary:'diaries',memory:'memories',event:'events'}[type]];return rows.filter(r=>r.deleted).map(r=>`<div class="card"><p>${esc((r.text||r.title||'').slice(0,120))}</p>${btn('restore-record','恢复',`data-id="${r.id}" data-kind="${type}"`)}</div>`);}).join('')||empty('没有被移除的内容。');break;
  case 'tasks':
    title='生成记录';html=tasksHTML(scope)+scope.tasks.filter(t=>t.status==='done').slice(-20).reverse().map(t=>`<div class="card"><strong>${esc(t.authorName||'角色')} · 已保存</strong>${meta(t.trace?.model||'')}${meta(`使用背景：${t.trace?.backgroundUsed?'是':'否'} · 使用回忆：${t.trace?.memoryIds?.length||0} 条`)}${meta(dateTime(t.at))}</div>`).join('');break;
  case 'confirm':title=route.title;html=`<p class="hint">${esc(route.message)}</p><div class="sheet-actions">${btn('cancel','取消','','secondary')}${btn(route.action,route.label||'确认',route.extra||'','primary')}</div>`;break;
  default:title='小手机';html=empty('从桌面打开一个应用吧。');
  }
  return {...common,title,html};
}
